    NutrientParserV1.tryParseAt = function(s, start) {
      const out = new NutrientScanResult();
      const sLen = s.length;
      const i = V1SharedHelpers.skipWhitespace(s, start);
      if (i >= sLen) {
        return out;
      }
      const numEnd = V1SharedHelpers.splitNumAndUnit(s.substring(i, sLen));
      if (numEnd <= 0) {
        return out;
      }
      const numPart = s.substring(i, i + numEnd);
      const isDec = V1SharedHelpers.isDecimalToken(numPart);
      if (isDec == false) {
        return out;
      }
      const afterNum = i + numEnd;
      if (afterNum >= sLen) {
        return out;
      }
      const tail = s.substring(afterNum, sLen);
      const isKcal = V1SharedHelpers.hasPrefix(tail, "kcal");
      if (isKcal) {
        out.found = true;
        out.name = "kcal";
        out.value = numPart;
        out.unit = "kcal";
        out.nextPos = afterNum + 4;
        return out;
      }
      const slashPos = V1SharedHelpers.findToken(tail, "/");
      if (slashPos <= 0) {
        return out;
      }
      const unitPart = tail.substring(0, slashPos);
      const nameStart = slashPos + 1;
      let nameEnd = tail.length;
      let ni = nameStart;
      while (ni < tail.length) {
        const ch = tail.charCodeAt(ni);
        if (V1SharedHelpers.isWhitespace(ch)) {
          nameEnd = ni;
          ni = tail.length;
        } else {
          ni = ni + 1;
        }
      }
      ;
      const namePart = tail.substring(nameStart, nameEnd).trim();
      if (unitPart.length == 0) {
        return out;
      }
      if (namePart.length == 0) {
        return out;
      }
      out.found = true;
      out.name = namePart;
      out.value = numPart;
      out.unit = unitPart;
      out.nextPos = afterNum + nameEnd;
      return out;
    };
