    FoodParserV1.parse = function(line) {
      const n = new FoodNode();
      let prefixLen = 5;
      if (line.length >= 4) {
        if (line.charCodeAt(4) != 32) {
          prefixLen = 4;
        }
      }
      if (line.length <= prefixLen) {
        return n;
      }
      let rest = line.substring(prefixLen, line.length).trim();
      const pipeOnly = V1SharedHelpers.hasPrefix(rest, "|");
      if (pipeOnly) {
        const descOnly = rest.substring(1, rest.length).trim();
        if (descOnly.length > 0) {
          n.hasDescription = true;
          n.description = descOnly;
        }
        return n;
      }
      const desc = V1SharedHelpers.extractPipeDescription(rest);
      if (desc.length > 0) {
        n.hasDescription = true;
        n.description = desc;
        const barPos = V1SharedHelpers.findToken(rest, "|");
        if (barPos >= 0) {
          rest = rest.substring(0, barPos).trim();
        }
      }
      let cursor = 0;
      const sLen = rest.length;
      while (cursor < sLen) {
        const scan = NutrientParserV1.tryParseAt(rest, cursor);
        if (scan.found == false) {
          cursor = sLen;
        } else {
          if (scan.name == "kcal") {
            n.hasCalories = true;
            n.caloriesRaw = scan.value;
          } else {
            if (scan.name == "prot") {
              n.hasProtein = true;
              n.proteinRaw = scan.value;
            } else {
              if (scan.name == "protein") {
                n.hasProtein = true;
                n.proteinRaw = scan.value;
              } else {
                if (scan.name == "carb") {
                  n.hasCarbs = true;
                  n.carbsRaw = scan.value;
                } else {
                  if (scan.name == "carbs") {
                    n.hasCarbs = true;
                    n.carbsRaw = scan.value;
                  } else {
                    if (scan.name == "fat") {
                      n.hasFat = true;
                      n.fatRaw = scan.value;
                    } else {
                      n.nutrientJsonList.push(NutrientParserV1.nutrientJson(
                        scan.name,
                        scan.value,
                        scan.unit
                      ));
                    }
                  }
                }
              }
            }
          }
          cursor = scan.nextPos;
        }
      }
      ;
      return n;
    };
