    CalendarWizard.strengthScore = function(pw) {
      const n = pw.length;
      if (n == 0) {
        return 0;
      }
      let score = 0;
      if (n >= 8) {
        score = score + 1;
      }
      if (n >= 12) {
        score = score + 1;
      }
      let lower = false;
      let upper = false;
      let digit = false;
      let other = false;
      let i = 0;
      while (i < n) {
        const c = pw.charCodeAt(i);
        if (c >= 97 && c <= 122) {
          lower = true;
        } else {
          if (c >= 65 && c <= 90) {
            upper = true;
          } else {
            if (c >= 48 && c <= 57) {
              digit = true;
            } else {
              other = true;
            }
          }
        }
        i = i + 1;
      }
      ;
      if (lower && upper) {
        score = score + 1;
      }
      if (digit) {
        score = score + 1;
      }
      if (other) {
        score = score + 1;
      }
      return score;
    };
