      openRoute(route) {
        const q = RtEntry.findIn(route, "?week=");
        if (q >= 0) {
          this.weekStart = RtWeek.mondayOf(route.substring(q + 6, q + 16));
        }
        if (RtEntry.hasPrefix(route, "/summary/yearsheet") || RtEntry.hasPrefix(route, "/yearsheet")) {
          let tail = "";
          if (RtEntry.hasPrefix(route, "/summary/yearsheet/")) {
            tail = route.substring(19, route.length);
          }
          if (RtEntry.hasPrefix(route, "/yearsheet/")) {
            tail = route.substring(11, route.length);
          }
          this.ys.openList();
          if (tail.length > 0) {
            this.ys.openDetail();
          }
          this.docScroll = 0;
          this.scene = "yearsheet";
          this.rebuild();
          return true;
        }
        if (RtEntry.hasPrefix(route, "/new-calendar")) {
          this.wizard.open();
          this.wizScroll = 0;
          this.scene = "wizard";
          this.rebuild();
          return true;
        }
        if (RtEntry.hasPrefix(route, "/calendar/")) {
          const rest_1 = route.substring(10, route.length);
          const qm = RtEntry.findIn(rest_1, "?");
          let id = rest_1;
          if (qm >= 0) {
            id = rest_1.substring(0, qm);
          }
          this.seed.selectCalendar(id);
          this.section = "calendar";
          this.calTab = "weeks";
        }
        if (route == "/" || route == "/home") {
          this.section = "home";
        }
        this.scene = "app";
        this.rebuild();
        return true;
      }
      restMs() {
        if (this.rest.value == "30") {
          return 3e4;
        }
        if (this.rest.value == "90") {
          return 9e4;
        }
        if (this.rest.value == "120") {
          return 12e4;
        }
        return 6e4;
      }
      adopt(host, rows) {
        let i = 0;
        while (i < rows.length) {
          const row = rows[i];
          const found = _RealTrainerDemo.byId(host, row.tid);
          if (typeof found != "undefined") {
            const el = found;
            if (row.role > 0) {
              el.role = EVGA11yRole.ariaName(row.role);
            }
            if (row.name.length > 0) {
              el.a11yLabel = row.name;
            }
            el.a11yExpanded = row.expanded;
            el.a11yChecked = row.checked;
            el.a11ySelected = row.selected;
            el.a11yPressed = row.pressed;
            el.a11ySorted = row.sorted;
            el.a11yDisabled = row.disabled;
            el.a11yLevel = row.level;
            el.a11ySetSize = row.setSize;
            el.a11yPosInSet = row.setPos;
            el.a11yOrientation = row.orientation;
            el.a11yCurrent = row.current;
            el.a11yRoleDescription = row.roleDescription;
            el.a11yHasPopup = row.hasPopup;
            el.a11yHasRange = row.hasRange;
            el.a11yValueMin = row.valueMin;
            el.a11yValueMax = row.valueMax;
            el.a11yHasValue = row.hasValueNow;
            el.a11yValueNow = row.valueNow;
            if (row.focusable) {
              el.a11yFocusable = true;
            }
          }
          i = i + 1;
        }
        ;
      }
