      pressPlan(id) {
        if (id == "rt-plan") {
          if (this.scene != "dashboard") {
            return false;
          }
          return this.plan.open(true, "cal-1");
        }
        if (this.plan.isOpen() == false) {
          return false;
        }
        if (id == "rt-plan-cancel" || id == "rt-plan-close") {
          this.modalScroll = 0;
          return this.plan.close();
        }
        if (id == "rt-plan-prev") {
          return this.plan.shiftWeek(-1);
        }
        if (id == "rt-plan-next") {
          return this.plan.shiftWeek(1);
        }
        if (_RealTrainerDemo.owns(this.weekType.tids(), id)) {
          this.weekType.activate(id);
          return this.plan.setWeekType(this.weekType.value);
        }
        if (id == "rt-plan-instr") {
          return this.plan.setInstructions("Kevyt viikko, painotus tekniikkaan");
        }
        if (id == "rt-plan-edit") {
          return this.plan.openEdit();
        }
        if (id == "rt-plan-confirm") {
          const week = this.seed.entriesInWeek(this.plan.text("targetWeekStart"));
          let ids = [];
          let dates = [];
          for (let i = 0; i < week.length; i++) {
            var e = week[i];
            ids.push(e.id);
            dates.push(e.date);
          }
          ;
          return this.plan.confirmWeekWith(ids, dates);
        }
        if (id == "rt-plan-go") {
          const started = this.plan.confirmReplacement();
          if (started) {
            this.planJob.failNext = this.backend.failNext;
            this.planJob.begin("plan");
          }
          return started;
        }
        if (id == "rt-plan-feedback") {
          return this.plan.setFeedback("Enemm\xE4n vetoja, v\xE4hemm\xE4n juoksua");
        }
        if (id == "rt-plan-reverse") {
          return this.plan.reverseDays();
        }
        if (id == "rt-plan-regen") {
          const regen = this.plan.startRegenerating();
          if (regen) {
            this.planJob.failNext = this.backend.failNext;
            this.planJob.begin("regenerate");
          }
          return regen;
        }
        const day = _RealTrainerDemo.dayOf(id, "rt-plan-day-");
        if (day >= 0) {
          return this.plan.setReplace(day, this.plan.flagIn("replaceSelectedByDay", day) == false);
        }
        const keep = _RealTrainerDemo.dayOf(id, "rt-plan-keep-");
        if (keep >= 0) {
          return this.plan.setKeep(keep, this.plan.flagIn("keepSameByDay", keep) == false);
        }
        const show = _RealTrainerDemo.dayOf(id, "rt-plan-show-");
        if (show >= 0) {
          return this.plan.setShowPrevious(show, this.plan.flagIn("showPreviousByDay", show) == false);
        }
        const accept = _RealTrainerDemo.dayOf(id, "rt-plan-accept-");
        if (accept >= 0) {
          return this.plan.setKeep(accept, true);
        }
        const copy = _RealTrainerDemo.dayOf(id, "rt-plan-copy-");
        if (copy >= 0) {
          const period = this.seed.firstPeriod();
          const week_1 = period.weekOf(this.exWeekType);
          return this.plan.setDayInstructions(copy, week_1.dayAt(copy));
        }
        const instr = _RealTrainerDemo.dayOf(id, "rt-plan-instr-");
        if (instr >= 0) {
          return this.plan.setDayInstructions(instr, "Pitk\xE4 juoksu, rauhallinen");
        }
        return false;
      }
