      drillSummaries() {
        const key = this.seed.entries.length.toString() + ("/" + this.seed.calendars.length.toString());
        if (key == this.drillCacheKey) {
          return this.drillCache;
        }
        let cals = [];
        for (let i = 0; i < this.seed.calendars.length; i++) {
          var c = this.seed.calendars[i];
          const sc = new ExerciseStatsCalendar();
          sc.id = c.id;
          sc.name = c.name;
          sc.type = c.kind;
          cals.push(sc);
        }
        ;
        let batches = [];
        const inOrder = this.seed.storeOrder();
        for (let ci = 0; ci < inOrder.length; ci++) {
          var c_1 = inOrder[ci];
          let own = [];
          for (let j = 0; j < this.seed.entries.length; j++) {
            var e = this.seed.entries[j];
            if (e.calendarId == c_1.id) {
              own.push(e);
            }
          }
          ;
          const ordered = _RealTrainerDemo.sortByDateDesc(own);
          for (let j_1 = 0; j_1 < ordered.length; j_1++) {
            var e_1 = ordered[j_1];
            if (e_1.compact.length == 0) {
              continue;
            }
            const doc_1 = CompactRowMapper.parseDocument(e_1.compact);
            for (let ri = 0; ri < doc_1.rows.length; ri++) {
              var row = doc_1.rows[ri];
              const items = _RealTrainerDemo.walkItemsOf(row, e_1.date);
              for (let k = 0; k < items.length; k++) {
                var item = items[k];
                const batch = new ExerciseStatsParsedItem();
                batch.calendarId = e_1.calendarId;
                batch.item = item;
                batches.push(batch);
              }
              ;
            }
            ;
          }
          ;
        }
        ;
        const opts = new CollectExercisesOptions();
        opts.excludePlans = true;
        this.drillCache = ExerciseStats.collectFromItems(cals, batches, opts);
        this.drillCacheKey = key;
        return this.drillCache;
      }
