      pressApp(id) {
        if (id == "rt-calsel") {
          this.calMenuOpen = this.calMenuOpen == false;
          return true;
        }
        if (this.calMenuOpen) {
          this.calMenuOpen = false;
          if (id == "rt-cal-new") {
            this.openRoute("/new-calendar");
            return true;
          }
          if (RtEntry.hasPrefix(id, "rt-cal-")) {
            if (this.seed.selectCalendar(id.substring(7, id.length))) {
              this.dayIso = "";
              this.goSection("home");
              this.section = "home";
            }
            return true;
          }
        }
        if (this.moreOpen) {
          if (id == "rt-more-close" || id == "rt-nav-more") {
            this.moreOpen = false;
            return true;
          }
          if (id == "rt-more-yearsheet") {
            this.moreOpen = false;
            this.ys.openList();
            this.docScroll = 0;
            this.scene = "yearsheet";
            return true;
          }
          if (id.length > 7) {
            if (id.substring(0, 7) == "rt-nav-") {
              this.moreOpen = false;
            } else {
              if (id.length > 8) {
                if (id.substring(0, 8) == "rt-more-") {
                  this.moreOpen = false;
                  return true;
                }
              }
              return false;
            }
          } else {
            return false;
          }
        }
        if (id == "rt-nav-home") {
          return this.goSection("home");
        }
        if (id == "rt-nav-calendar") {
          this.weekStart = RtWeek.mondayOf(this.today);
          this.goSection("calendar");
          return true;
        }
        if (id == "rt-nav-dashboard") {
          return this.goSection("dashboard");
        }
        if (id == "rt-dash-open") {
          this.ys.openList();
          this.ys.openDetail();
          this.docScroll = 0;
          this.scene = "yearsheet";
          return true;
        }
        if (id == "rt-nav-chat") {
          return this.goSection("chat");
        }
        if (id == "rt-nav-more") {
          this.moreOpen = true;
          return true;
        }
        if (RtEntry.hasPrefix(id, "rt-drill-cat-")) {
          this.drillCat = id.substring(13, id.length);
          this.drillSortOpen = false;
          return true;
        }
        if (id == "rt-drill-sort") {
          this.drillSortOpen = this.drillSortOpen == false;
          return true;
        }
        if (RtEntry.hasPrefix(id, "rt-drill-sort-")) {
          this.drillSort = id.substring(14, id.length);
          this.drillSortOpen = false;
          return true;
        }
        if (RtEntry.hasPrefix(id, "rt-home-tab-")) {
          const tab = id.substring(12, id.length);
          if (tab == this.homeTab) {
            return false;
          }
          this.homeTab = tab;
          this.docScroll = 0;
          return true;
        }
        if (id == "rt-plan-update" || id == "rt-plan-create") {
          const opened = this.plan.open(true, "cal-plan");
          if (opened) {
            this.plan.setWeekType(this.exWeekType);
            const e = ScEvent.of("SET_WEEK_START");
            e.withStr("weekStart", this.weekStart);
            this.plan.send(e);
          }
          return opened;
        }
        if (this.section != "calendar") {
          return false;
        }
        if (id == "rt-day-back" || id == "rt-day-close") {
          if (this.dayIso.length == 0) {
            return false;
          }
          this.dayIso = "";
          return true;
        }
        if (RtEntry.hasPrefix(id, "rt-day-20")) {
          this.dayIso = id.substring(7, id.length);
          this.docScroll = 0;
          return true;
        }
        if (id == "rt-week-next") {
          this.weekStart = RtWeek.shifted(this.weekStart, 7);
          return true;
        }
        if (id == "rt-week-prev") {
          this.weekStart = RtWeek.shifted(this.weekStart, -7);
          return true;
        }
        if (id == "rt-week-today") {
          this.weekStart = RtWeek.mondayOf(this.today);
          return true;
        }
        if (id == "rt-tab-weeks") {
          this.calTab = "weeks";
          return true;
        }
        if (id == "rt-tab-example") {
          this.calTab = "example";
          return true;
        }
        if (id == "rt-week-target") {
          this.exWeekType = "target";
          return true;
        }
        if (id == "rt-week-light") {
          this.exWeekType = "light";
          return true;
        }
        if (id == "rt-ex-edit") {
          return this.plan.openEdit();
        }
        return false;
      }
