      data.numbers("v", def0.values);
      const last = VlDataset.create();
      let lastX = [];
      let lastV = [];
      lastX.push(parseFloat(n - 1));
      lastV.push(def0.values[n - 1]);
      last.numbers("i", lastX);
      last.numbers("v", lastV);
      const xScale = RealTrainerDemo2.domainJson(0, parseFloat(n - 1));
      const yScale = RealTrainerDemo2.domainJson(lo, hi);
